  ('physics-board-rajshahi-2024-mcq-023', 'class9-physics-bn-guide', 'satt-physics-board.pdf p35', 'লেখচিত্র অনুযায়ী- i. BC ও DE অংশের তাপমাত্রার পার্থক্য সমান ii. AB অংশে প্রয়োজনীয় তাপ 2100 J iii. বরফ গলা পানিতে পরিণত হতে 6 min সময় লাগে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i","খ":"i ও ii","গ":"i ও iii","ঘ":"ii ও iii"}'::jsonb, 'খ', 1, false, 'physics-board-rajshahi-2024-mcq', false, 'board-mcq', null, null, 'rajshahi', 2024, true),
  ('physics-board-rajshahi-2024-mcq-024', 'class9-physics-bn-guide', 'satt-physics-board.pdf p35', 'বর্তনীর তু ল্যরোধ কত?', 'mcq', '{"ক":"3. 94 Ω","খ":"5. 5 Ω","গ":"8. 1Ω","ঘ":"8. 55 Ω"}'::jsonb, 'খ', 1, false, 'physics-board-rajshahi-2024-mcq', false, 'board-mcq', null, null, 'rajshahi', 2024, true),
  ('physics-board-rajshahi-2024-mcq-025', 'class9-physics-bn-guide', 'satt-physics-board.pdf p35', 'উক্ত বর্তনীতে- i. R2 ও R4 এর তড়িৎ প্রবাহ একই ii. R3 এর বিভব পার্থক্য R2 এর বিভব পার্থক্য অপেক্ষা বেশি iii. R1 এর ক্ষমতা 8W নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', 1, false, 'physics-board-rajshahi-2024-mcq', false, 'board-mcq', null, null, 'rajshahi', 2024, true),
  ('physics-board-sylhet-2024-mcq-001', 'class9-physics-bn-guide', 'satt-physics-board.pdf p23', 'সুর শলাকা থেকে সৃষ্ট তরঙ্গের পর্যায়কাল কত?', 'mcq', '{"ক":"0.0005 s","খ":"0.005 s","গ":"0.05 s","ঘ":"0.5 s"}'::jsonb, 'ক', 1, false, 'physics-board-sylhet-2024-mcq', false, 'board-mcq', null, 'একটি সুর শলাকার কম্পাঙ্ক 2 kHz। সুর শলাকা থেকে সৃষ্ট শব্দ বায়ু মাধ্যমে 340 ms-1 বেগে গমন করতে পারে।', 'sylhet', 2024, true),
  ('physics-board-sylhet-2024-mcq-002', 'class9-physics-bn-guide', 'satt-physics-board.pdf p23', 'সৃষ্ট তরঙ্গের ক্ষেত্রে- i. যান্ত্রিক তরঙ্গ ii. তরঙ্গদৈর্ঘ্য 0.17 m iii. তরঙ্গশীর্ষ ও তরঙ্গপাদ সৃষ্টি হয় নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', 1, false, 'physics-board-sylhet-2024-mcq', false, 'board-mcq', null, 'একটি সুর শলাকার কম্পাঙ্ক 2 kHz। সুর শলাকা থেকে সৃষ্ট শব্দ বায়ু মাধ্যমে 340 ms-1 বেগে গমন করতে পারে।', 'sylhet', 2024, true),
  ('physics-board-sylhet-2024-mcq-003', 'class9-physics-bn-guide', 'satt-physics-board.pdf p23', 'বস্তুটিকে কত বেগে উপরের দিকে নিক্ষেপ করা হয়েছিল?', 'mcq', '{"ক":"0.4 m/s","খ":"0.632 m/s","গ":"20 m/s","ঘ":"400 m/s"}'::jsonb, 'গ', 1, false, 'physics-board-sylhet-2024-mcq', false, 'board-mcq', null, '"50gm ভরের একটি বস্তুকে 10J গতিশক্তিতে খাড়া উপরের দিকে নিক্ষেপ করা হয়।"', 'sylhet', 2024, true),
  ('physics-board-sylhet-2024-mcq-004', 'class9-physics-bn-guide', 'satt-physics-board.pdf p23', 'প্রথম অর্ধেক দূরত্ব অতিক্রমের পর বস্তুটির বেগ কত হবে?', 'mcq', '{"ক":"4.472 m/s","খ":"10 m/s","গ":"14.14 m/s","ঘ":"17.32 m/s"}'::jsonb, 'গ', 1, false, 'physics-board-sylhet-2024-mcq', false, 'board-mcq', null, '"50gm ভরের একটি বস্তুকে 10J গতিশক্তিতে খাড়া উপরের দিকে নিক্ষেপ করা হয়।"', 'sylhet', 2024, true),
  ('physics-board-sylhet-2024-mcq-005', 'class9-physics-bn-guide', 'satt-physics-board.pdf p23', 'প্রদর্শিত বর্তনীর জন্য- i. তিনটি রোধকের বিভব পার্থক্য ভিন্ন হবে ii. সকল রোধের জন্য বিদ্যুৎ প্রবাহ অপরিবর্তিত থাকবে iii. ''B'' বিন্দুর বিভব ''C'' বিন্দুর বিভব অপেক্ষা কম হবে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', 1, false, 'physics-board-sylhet-2024-mcq', false, 'board-mcq', null, null, 'sylhet', 2024, true),
