  ('physics-board-sylhet-2024-mcq-008', 'class9-physics-bn-guide', 'satt-physics-board.pdf p25', 'লেন্সের 2 m সামনে প্রধান অক্ষের উপর কোনো বস্তু রাখা হলে i. বাস্তব প্রতিবিম্ব গঠিত হবে ii. বিবর্ধিত বিম্ব গঠিত হবে iii. প্রতিবিম্বের দূরত্ব− হবে 10 3 m নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'গ', 1, false, 'physics-board-sylhet-2024-mcq', false, 'board-mcq', null, null, 'sylhet', 2024, true),
